"""
Exceptions for the Agents service.

"""

from qbraid_core.exceptions import HttpStatusMixin, QbraidException


class AgentServiceError(QbraidException):
    """Base exception for agent service errors."""


class AgentServiceRequestError(HttpStatusMixin, AgentServiceError):
    """Exception raised when an agent service API request fails."""


class AgentSessionNotFoundError(HttpStatusMixin, AgentServiceError):
    """Exception raised when a session is not found."""


class AgentRegistryError(AgentServiceError):
    """Exception raised for registry read/write failures."""


class AgentDiscoveryError(AgentServiceError):
    """Exception raised when process discovery fails."""


class AgentTranscriptError(AgentServiceError):
    """Exception raised when transcript parsing fails."""


class AgentHookError(AgentServiceError):
    """Exception raised when hook installation fails."""


class AgentLauncherError(AgentServiceError):
    """Exception raised when agent launching fails."""


class AgentMessagingError(AgentServiceError):
    """Exception raised for messaging failures (delivery or permission)."""
